// pump's shape: a function stored in a module-level `var` and exported by
// reference after it is defined.
var once = require("oncelike");

var noop = function () {};

var pumpish = function () {
  var steps = Array.prototype.slice.call(arguments);
  var done = once(typeof steps[steps.length - 1] === "function" ? steps.pop() : noop);
  var total = steps.reduce(function (acc, n) {
    return acc + n;
  }, 0);
  done(total);
  return total;
};

module.exports = pumpish;
